INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/jiuwudaishi-118-january-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002780；EPUB电子本，纸本及异文待核", "id": "746a7826-3350-5fd8-b764-48b44a4e1f12"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/jiuwudaishi-118-march-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002782；EPUB电子本，纸本及异文待核", "id": "8af10a4a-0c69-5b2f-bbe1-167e16e440ad"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/tongjian-294-958-spring/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003486；电子底本待考，分段待核", "id": "4e99a784-f6f3-5071-813c-d629a46340d6"}, {"title": "新五代史·卷十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/xinwudaishi-12-chuzhou-capture/source.txt", "note": "《新五代史》卷十二，段落 xin-wudaishi-b08f244b9241-p000380；EPUB电子本，纸本及异文待核", "id": "770f521e-92b7-5f0e-8e5c-c13884f5189b"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8ed915b0f3bf92daf19318ca9962a9e6c2c54f00/content/books/zizhi-tongjian/vol-294/year-0958/part-01/sources/library/xinwudaishi-62-chuzhou-capture/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003153；EPUB电子本，纸本及异文待核", "id": "d21f28a5-bb7b-598f-bd98-c40ee7241cc0"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王汉璋", "aliases": ["王漢璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周右龙武将军。958年正月奏报海州战果，《通鉴》记丁亥奏克，《旧五代史》记丙戌奏攻，纪日和措辞分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "ee7caa90-e90b-5447-b9fa-b0286a86b25b"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "尹日就", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周左谏议大夫。《旧五代史》记957年寿州受降后，受命前往寿州开仓赈济饥民。生卒年未载。", "biography": null, "status": "draft", "id": "ed2f6a77-6008-5d03-a738-90913d39eeaa"}, {"name": "章九龄", "aliases": ["章九齡"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀右补阙。958年正月面见孟昶，指李昊、王昭远为奸佞而遭贬维州录事参军。与唐代宰相张九龄分别保存。生卒年未载。", "biography": null, "status": "draft", "id": "fddbccdc-9ed4-5c68-8196-59c4467f7ede"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "张彦卿", "aliases": ["張彥卿"], "era": "五代十国", "birth_year": null, "death_year": 958, "description": "南唐楚州防御使。958年正月城陷后仍与郑昭业及千余部众抵抗，兵器耗尽后以绳床搏战，最终战死。城破日主书与新史记丁未，旧史记丙午。", "biography": null, "status": "draft", "id": "1c2867f3-9d03-5deb-bfab-6bc746a09d43"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "郑昭业", "aliases": ["鄭昭業"], "era": "五代十国", "birth_year": null, "death_year": 958, "description": "南唐楚州都监。958年正月城陷后继续随张彦卿拒战，战死不降。具体生年未载。", "biography": null, "status": "draft", "id": "756c529a-8c73-5496-a046-0c395a3ea504"}, {"name": "张光祐", "aliases": ["張光祐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐守将张彦卿之子。《旧五代史》注文引陆游《南唐书》称楚州城破后，周军得到他而未杀。不得据另引未具名劝降子被父杀之说将两人合一。生卒年未载。", "biography": null, "status": "draft", "id": "7805e906-3b2b-55ee-966b-9c7e50d5742f"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}, {"name": "魏璘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荆南指挥使。958年奉高保融命率百艘战船东下，会攻南唐，抵鄂州。具体出发与抵达日未载。生卒年未载。", "biography": null, "status": "draft", "id": "193b0ed7-74ee-5193-aaeb-aed35d7984f0"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "后周废除匡国军", "start_year": 958, "end_year": 958, "time_original": "958年正月乙酉", "dynasty": "五代十国", "description": "后周废除匡国军。", "phases": [], "location_name": "匡国军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fdc237c9-d069-5a0e-99bc-54c2b18f283e"}, {"title": "南唐改元中兴", "start_year": 958, "end_year": 958, "time_original": "《资治通鉴》958年正月条，具体改元日未载", "dynasty": "五代十国", "description": "南唐改元中兴。", "phases": [], "location_name": "南唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2ec58ab5-5cbe-5027-b79b-8f1dd8944bbb"}, {"title": "王汉璋奏报攻克海州", "start_year": 958, "end_year": 958, "time_original": "《资治通鉴》958年正月丁亥奏报，交战日未载", "dynasty": "五代十国", "description": "王汉璋奏报攻克海州。", "phases": [], "location_name": "海州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9570ca4e-b6cb-5125-ac50-a420f235e0f5"}, {"title": "柴荣命韩令坤暂掌扬州军府事务", "start_year": 958, "end_year": 958, "time_original": "958年正月己丑", "dynasty": "五代十国", "description": "柴荣命韩令坤暂掌扬州军府事务。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1bc20656-7424-5384-891f-b3c5fdf9d04e"}, {"title": "周战舰受北神堰阻，柴荣考虑开鹳水通江", "start_year": 958, "end_year": 958, "time_original": "958年正月，具体规划日未载", "dynasty": "五代十国", "description": "周战舰受北神堰阻，柴荣考虑开鹳水通江。", "phases": [], "location_name": "北神堰、楚州西北鹳水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fb17faa6-3855-53ae-b2bb-db7299a2c2b1"}, {"title": "勘察使者报告水道施工困难，柴荣亲自察看并规划", "start_year": 958, "end_year": 958, "time_original": "958年正月开渠前，具体察看日未载", "dynasty": "五代十国", "description": "勘察使者报告水道施工困难，柴荣亲自察看并规划。", "phases": [], "location_name": "楚州西北鹳水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c2415e6f-29fe-5e64-a8a9-397b833e3176"}, {"title": "后周征楚州民夫开渠，十来日完工、百艘大舰通江", "start_year": 958, "end_year": 958, "time_original": "958年正月；《旧五代史》庚寅发丁壮，竣工日主记旬日后", "dynasty": "五代十国", "description": "后周征楚州民夫疏浚水道，史书称十来日完成、用工较省，百艘巨舰得以通江。南唐人大惊、以为神是史书记载的反应，不认可神迹，也不按旬日倒算精确竣工日期。", "phases": [], "location_name": "楚州鹳水通淮、江路线", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ba24de4e-36d5-5088-bca2-fa8f7733be03"}, {"title": "周军攻取静海军，打开通吴越的道路", "start_year": 958, "end_year": 958, "time_original": "958年正月壬辰", "dynasty": "五代十国", "description": "周军攻取静海军，打开通吴越的道路。", "phases": [], "location_name": "静海军至吴越路线", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "767cda3e-d278-57d5-b92f-c12ca4960edc"}, {"title": "柴荣派尹日就等使吴越，预测归程可走陆路", "start_year": null, "end_year": null, "time_original": "958年通吴越道路以前，具体派使年日未载", "dynasty": "五代十国", "description": "柴荣派尹日就等使吴越，预测归程可走陆路。", "phases": [], "location_name": "长安籍尹日就由周泛海赴吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "abf5bc02-9c48-528a-b5e3-987bfec24a6d"}, {"title": "《通鉴》记尹日就出使返程的预测后来实现", "start_year": null, "end_year": null, "time_original": "此前派使后，实际实现年月未载", "dynasty": "五代十国", "description": "《通鉴》记尹日就出使返程的预测后来实现。", "phases": [], "location_name": "吴越至后周陆路", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "78c33f72-1ee1-56f2-82f5-d4031c4c63a1"}, {"title": "章九龄指李昊、王昭远为奸佞，被孟昶贬维州", "start_year": 958, "end_year": 958, "time_original": "958年正月甲辰", "dynasty": "五代十国", "description": "章九龄指李昊、王昭远为奸佞，被孟昶贬维州。", "phases": [], "location_name": "后蜀朝廷至维州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f42cfa71-5341-583b-9e6b-83dae0e39241"}, {"title": "张彦卿固守楚州，周军攻四十余日未克", "start_year": null, "end_year": null, "time_original": "957年十二月至958年正月围攻期间，具体各次战日未载", "dynasty": "五代十国", "description": "张彦卿固守楚州，周军攻四十余日未克。", "phases": [], "location_name": "楚州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b289aae4-903f-55ee-94a7-3c4400d162f9"}, {"title": "柴荣亲督楚州攻城，宿城下", "start_year": 958, "end_year": 958, "time_original": "958年正月乙巳", "dynasty": "五代十国", "description": "柴荣亲督楚州攻城，宿城下。", "phases": [], "location_name": "楚州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6823b754-5450-5248-86bd-b7174da4e09e"}, {"title": "周军攻克楚州，守军继续拒战", "start_year": 958, "end_year": 958, "time_original": "《通鉴》《新五代史》958年正月丁未；《旧五代史》丙午", "dynasty": "五代十国", "description": "楚州城破后，张彦卿、都监郑昭业仍率千余部众拒战。箭与兵器用尽，张彦卿举绳床搏斗而死，史书称所部无一人投降。千余是守将所部，不当全城军民总数，绳床不误作绳子绞死。", "phases": [], "location_name": "楚州城内", "location_modern_name": null, "location_lat": null, "location_lng": null